 15→// droppedTypes are entry types that carry no parser-relevant data.
 16→var droppedTypes = map[string]bool{
 17→	"progress":              true,
 18→	"file-history-snapshot": true,
 19→	"queue-operation":       true,
 20→	"system":                true,
 21→}
 22→
 23→// CompactOptions provides metadata fields written to every output line.
 24→type CompactOptions struct {
 25→	Agent      string // e.g. "claude-code"
 26→	CLIVersion string // e.g. "0.42.0"
 27→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 28→}
 29→
 30→// compactMeta holds pre-computed JSON fragments for fields that are identical
 31→// on every output line, avoiding repeated marshaling.
 32→type compactMeta struct {
 33→	v          json.RawMessage
 34→	agent      json.RawMessage
 35→	cliVersion json.RawMessage
 36→}
 37→
 38→func newCompactMeta(opts CompactOptions) compactMeta {
 39→	return compactMeta{
 40→		v:          mustMarshal(1),
 41→		agent:      mustMarshal(opts.Agent),
 42→		cliVersion: mustMarshal(opts.CLIVersion),
 43→	}
 44→}
 45→
 46→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 47→//
 48→// The output format puts version, agent, and cli_version on every line,
 49→// flattens the message wrapper, and splits user tool results into separate entries:
 50→//
 51→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 52→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 53→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 54→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 55→	truncated := SliceFromLine(content, opts.StartLine)
 56→	if truncated == nil {
 57→		truncated = []byte{}
 58→	}
 59→
 60→	// Detect OpenCode format: a single JSON object with "info" and "messages" keys.
 61→	if isOpenCodeFormat(truncated) {
 62→		return compactOpenCode(truncated, opts)
 63→	}
 64→
 65→	meta := newCompactMeta(opts)
 66→	reader := bufio.NewReader(bytes.NewReader(truncated))
 67→	var result []byte
 68→
 69→	for {
 70→		lineBytes, err := reader.ReadBytes('\n')
 71→		if err != nil && err != io.EOF {
 72→			return nil, err
 73→		}
 74→
 75→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 76→			outputLines := convertLine(lineBytes, meta)
 77→			for _, ol := range outputLines {
 78→				result = append(result, ol...)
 79→				result = append(result, '\n')
 80→			}
 81→		}
 82→
 83→		if err == io.EOF {
 84→			break
 85→		}
 86→	}
 87→
 88→	return result, nil
 89→}
