273→// parseMessage extracts and parses the "message" field from a transcript line.
274→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
275→	msgRaw, ok := raw["message"]
276→	if ok {
277→		var msg map[string]json.RawMessage
278→		if json.Unmarshal(msgRaw, &msg) == nil {
279→			return msg
280→		}
281→	}
282→
283→	// Native Gemini transcript entries store id/content at top-level
284→	// rather than inside a nested "message" object.
285→	msg := make(map[string]json.RawMessage, 2)
286→	if v, has := raw["id"]; has {
287→		msg["id"] = v
288→	}
289→	if v, has := raw["content"]; has {
290→		msg["content"] = v
291→	}
292→	if len(msg) == 0 {
293→		return nil
294→	}
295→	return msg
296→}
