479→// compactOpenCode converts a full OpenCode session JSON into transcript lines.
480→func compactOpenCode(content []byte, opts CompactOptions) ([]byte, error) {
481→	var session struct {
482→		Messages []openCodeMessage `json:"messages"`
483→	}
484→	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
485→		return nil, fmt.Errorf("parsing opencode session: %w", err)
486→	}
487→
488→	meta := newCompactMeta(opts)
489→	var result []byte
490→
491→	for _, msg := range session.Messages {
492→		ts := msToTimestamp(msg.Info.Time.Created)
493→
494→		switch msg.Info.Role {
495→		case TypeUser:
496→			lines := convertOpenCodeUser(msg, ts, meta)
497→			for _, l := range lines {
498→				result = append(result, l...)
499→				result = append(result, '\n')
500→			}
501→		case TypeAssistant:
502→			lines := convertOpenCodeAssistant(msg, ts, meta)
503→			for _, l := range lines {
504→				result = append(result, l...)
505→				result = append(result, '\n')
506→			}
507→		}
508→	}
509→
510→	return result, nil
511→}
