513→func convertOpenCodeUser(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
514→	var texts []string
515→	for _, part := range msg.Parts {
516→		if unquote(part["type"]) == ContentTypeText {
517→			text := textutil.StripIDEContextTags(unquote(part[ContentTypeText]))
518→			if text != "" {
519→				texts = append(texts, text)
520→			}
521→		}
522→	}
523→
524→	b := marshalOrdered(
525→		"v", meta.v,
526→		"agent", meta.agent,
527→		"cli_version", meta.cliVersion,
528→		"type", mustMarshal(TypeUser),
529→		"ts", ts,
530→		"content", mustMarshal(strings.Join(texts, "\n\n")),
531→	)
532→	if b == nil {
533→		return nil
534→	}
535→	return [][]byte{b}
536→}
