594→// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
595→func msToTimestamp(ms int64) json.RawMessage {
596→	if ms == 0 {
597→		return nil
598→	}
599→	t := time.UnixMilli(ms).UTC()
600→	return mustMarshal(t.Format(time.RFC3339Nano))
601→}
